def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    # Find the L-shaped marker by how much of its component lies on
    # its dominant row and dominant column.
    guides = []
    for color, cells in comps:
        rows, cols = {}, {}
        for y, x in cells:
            rows[y] = rows.get(y, 0) + 1
            cols[x] = cols.get(x, 0) + 1
        if len(rows) < 3 or len(cols) < 3:
            continue
        arm_y = max(rows, key=rows.get)
        stem_x = max(cols, key=cols.get)
        overlap = sum(1 for y, x in cells if y == arm_y or x == stem_x)
        guides.append((overlap / len(cells), len(cells), color, cells, arm_y, stem_x))

    if not guides:
        return grid
    _, _, marker_color, marker, arm_y, stem_x = max(guides)

    arm_xs = [x for y, x in marker if y == arm_y]
    arm_left = min(arm_xs) < stem_x
    out = [row[:] for row in grid]

    candidates = [(color, cells) for color, cells in comps if cells is not marker]
    if not candidates:
        return out

    if arm_left:
        # When the arm points left, follow its outer tip downward.
        tip_x = min(arm_xs)
        possible = []
        for color, cells in candidates:
            below = [(y, x) for y, x in cells if y > arm_y and x <= stem_x]
            if below:
                d = min((y - arm_y) + abs(x - tip_x) for y, x in below)
                possible.append((d, -len(cells), cells))
        if possible:
            target = min(possible, key=lambda z: (z[0], z[1]))[2]
        else:
            target = min(candidates, key=lambda item: min(
                abs(y - arm_y) + abs(x - stem_x) for y, x in item[1]))[1]
    else:
        # Follow the horizontal line back from the elbow and take the
        # closest object encountered on that side.
        possible = []
        for color, cells in candidates:
            left_cells = [(y, x) for y, x in cells if x < stem_x]
            if not left_cells:
                continue
            ray_dist = min(abs(y - arm_y) for y, x in left_cells)
            along_dist = min(stem_x - x for y, x in left_cells)
            possible.append((ray_dist, along_dist, -len(cells), cells))
        if possible:
            target = min(possible, key=lambda z: z[:3])[3]
        else:
            target = min(candidates, key=lambda item: min(
                abs(y - arm_y) + abs(x - stem_x) for y, x in item[1]))[1]

    for y, x in target:
        out[y][x] = marker_color
    return out
